export const LOGS={};
const script={intro:[['ghju','Les souvenirs de GAB-1 et CAR-14 nous ont conduits ici.'],['voss','Le complexe BIO-LAB héberge les archives du programme PINK.']],security:[['voss','Le poste de surveillance verrouille le BIO-LAB. Passez par la rampe de maintenance.']],'security-data':[['cara','Je détourne le canal d’identification. Les codes sont copiés.']],bridge:[['lylu','Les unités contrôlent le viaduc. On avance à couvert.']],'bio-scan':[['gaby','Les capteurs détectent des signatures humaines. Ces expériences sont toujours en cours.']],research:[['cara','Le secteur B1 contient les interfaces de transfert.']],'research-data':[['lylu','Ces signatures sont celles de consciences, pas de simples programmes.']],'archive-backup':[['voss','Conservez les preuves, même si ORDRE détruit le complexe.']],'archive-exit':[['cara','Le verrouillage des archives est neutralisé.']],'stase-power':[['gaby','Je maintiens les fonctions vitales pendant que vous coupez le circuit.']],quarantine:[['ghju','Il reste des sujets dans cette annexe.']],'quarantine-data':[['voss','Les accès de quarantaine sont libres. AEGIS prépare leur prise en charge.']],'truth-data':[['lylu','On garde une copie. Personne ne doit pouvoir effacer leurs souvenirs.']],regulation:[['cara','Le programme bascule sur les régulateurs haute tension.']],'regulation-b':[['gaby','Je désynchronise les deux circuits.']],'shutdown':[['voss','Le noyau est vulnérable. Tenez la position.']],access:[['voss','Accès ouvert. Rejoignez le laboratoire.']],bio:[['cara','Ces cuves sont encore alimentées.']],archives:[['lylu','Les fichiers décrivent un transfert de conscience.']],stase:[['ghju','Libérons les sujets. Ils sont vivants.']],verite:[['gaby','Gabrielle. C’est mon nom.'],['cara','Et moi, Carla. ORDRE a enfermé nos consciences dans les sphères.'],['ghju','Vous êtes nos petites sœurs.']],noyau:[['voss','Désactivez le noyau. Empêchez ORDRE de reproduire le programme.']],evacuation:[['lylu','On part tous ensemble.']],fin:[['gaby','Vous nous avez retrouvées.']]};
export const linesFor=id=>(script[id]||[]).map(([who,text])=>({who,text,speaker:speakers[who]}));
export const lineSeconds=text=>Math.max(3.5,text.length/17);export const logFor=()=>null;
